I = [[1,0,1,2,0],[0,1,2,1,0],[1,2,3,1,1],[0,1,1,2,0],[1,0,2,1,0]]
K = [[1,0,-1],[1,0,-1],[1,0,-1]]
conv = []
for r in range(len(I)-len(K)+1):
    row = []
    for c in range(len(I[0])-len(K[0])+1):
        s = 0
        for a in range(len(K)):
            for b in range(len(K[0])):
                s += I[r+a][c+b] * K[a][b]
        row.append(s)
    conv.append(row)
print(len(conv))
print(conv[0][0])
print(len(K)*len(K[0])*1*1 + 1)
relu = [[max(0, v) for v in row] for row in conv]
pool_size = 2
stride = 1
pout = (len(relu) - pool_size)//stride + 1
print(pout)
for r in range(pout):
    for c in range(pout):
        m = relu[r][c]
        for a in range(pool_size):
            for b in range(pool_size):
                if relu[r+a][c+b] > m:
                    m = relu[r+a][c+b]
        print(m)
